class Orin < Formula
  desc "Compiler for Orin, a statically typed language with verified contracts"
  homepage "https://github.com/orin-lang/orin-lang"
  version "0.1.0-beta.1"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/orin-lang/orin-lang/releases/download/v0.1.0-beta.1/orin-0.1.0-beta.1-macos-arm64.tar.gz"
      sha256 "f57f68cb37816ed62b69ac3055a5c5e755dc2acfb55f0a71720c0fda7543ff26"
    end
    on_intel do
      url "https://github.com/orin-lang/orin-lang/releases/download/v0.1.0-beta.1/orin-0.1.0-beta.1-macos-x86_64.tar.gz"
      sha256 "c4e941a724e9815f65c791130bb6409680444013d81e04107b94884ec9721a19"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/orin-lang/orin-lang/releases/download/v0.1.0-beta.1/orin-0.1.0-beta.1-linux-x86_64.tar.gz"
      sha256 "65c084035c82fb58e29f9b10a41e86ca21d8cd3031162ed5df011054e3f5abab"
    end
    on_arm do
      url "https://github.com/orin-lang/orin-lang/releases/download/v0.1.0-beta.1/orin-0.1.0-beta.1-linux-aarch64.tar.gz"
      sha256 "447054ba19080df0b7019d033f26a829a6453c2b68c299041b5b255eb037646f"
    end
  end

  def install
    # The release package is relocatable: bin/orin finds libexec/ and lib/orin/ relative to itself, so the whole
    # package goes to libexec and bin/orin is a wrapper that execs the real launcher by its path.
    libexec.install Dir["*"]
    bin.write_exec_script libexec/"bin/orin"
  end

  def caveats
    <<~EOS
      orin compiles through C: it needs a C compiler on PATH (Xcode Command Line Tools on macOS, gcc or clang on
      Linux). Run `orin doctor` to check the toolchain. Getting started:
        https://github.com/orin-lang/orin-lang/blob/main/docs/tutorial/README.md
    EOS
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/orin --version").strip
    system bin/"orin", "doctor"
    (testpath/"hello.or").write <<~ORIN
      function main(): void {
        console.log("Hello from Homebrew!");
      }
    ORIN
    assert_equal "Hello from Homebrew!", shell_output("#{bin}/orin run hello.or").strip
    system bin/"orin", "build", "hello.or", "-o", "hello"
    assert_equal "Hello from Homebrew!", shell_output("./hello").strip
  end
end
